func calculateDepth(group string) int {
    depth := 0
    maxDepth := 0

    for _, char := range group {
        if char == '(' {
            depth++
        } else if char == ')' {
            depth--
        }

        maxDepth = max(maxDepth, depth)
    }

    return maxDepth
}

