func SortNumbers(numbers string) string {
    numberStr := strings.Split(numbers, " ")
    sort.Slice(numberStr, func(i, j int) bool {
        return convertToInt(numberStr[i]) < convertToInt(numberStr[j])
    })
    return strings.Join(numberStr, " ")
}

func convertToInt(num string) int {
    switch num {
    case "zero":
        return 0
    case "one":
        return 1
