    func CorrectBracketing(brackets string) bool {
    if len(brackets)%2 != 0 {
        return false
    }

    stack := make([]rune, 0)
    for _, char := range brackets {
        if char == '<' {
            stack = append(stack, char)
        } else if char == '>' {
            if len(stack) == 0 {
                return false
            }
            stack = stack[:len(stack)-1]
        }
    }

    return len(stack) == 0
}

