    import "sort"

func CorrectBracketing(brackets string) bool {
    if len(brackets)%2 != 0 {
        return false
    }

    opening := []byte{}
    closing := []byte{}

    for i := 0; i < len(brackets); i++ {
        if brackets[i] == '<' {
            opening = append(opening, brackets[i])
        } else if brackets[i] == '>' {
            closing = append(closing, brackets[i])
        }
    }

    sort.Slice(opening, func(i, j int) bool { return opening[i] < opening[j] })
    sort.Slice(closing, func(i, j int) bool { return closing[i] < closing[j] })

    for i := 0; i < len(opening); i++ {
        if opening[i] != closing[i] {
            return false
        }
    }

    return true
}

