	result := ""
	for _, digit := range digits {
		result += strconv.Itoa(digit)
	}

	return result
}

func reverse(s string) string {
	runes := []rune(s)
	for i, j := 0, len(runes)-1; i < j; i, j = i+1, j-1 {
		runes[i], runes[j] = runes[j], runes[i]
	}
	return string(runes)
}

func findMaxIndex(nums []int) int {
	maxIdx := 0
	for i, num := range nums {
		if num > nums[maxIdx] {
			maxIdx = i
		}
	}
	return maxIdx
}

