func findMinAndMax(lst []int) (int, int) {
    min, max := lst[0], lst[0]

    for i := 1; i < len(lst); i++ {
        if lst[i] < min {
            min = lst[i]
        }
        if lst[i] > max {
            max = lst[i]
        }
    }

    return min, max
}

func removeElement(lst []int, elem int) []int {
    index := -1

    for i, val := range lst {
        if val == elem {
            index = i
            break
        }
    }

    if index == -1 {
        return lst
    }

    return append(lst[:index], lst[index+1:]...)
}

