    func IsSimplePower(x int, n int) bool {
	if x == 1 {
		return true
	}

	for i := 1; i <= x; i++ {
		result := 1
		pow := n
		for result < x {
			result *= pow
			if result == x {
				return true
			}
		}
	}

	return false
