    import "sort"

func GetRow(lst [][]int, x int) [][2]int {
    result := make([][2]int, 0)
    type coord struct {
        row, col int
    }
    coordinates := make([]coord, 0)

    for i, row := range lst {
        for j, num := range row {
            if num == x {
                coordinates = append(coordinates, coord{i, j})
            }
        }
    }

    sort.Slice(coordinates, func(i, j int) bool {
        if coordinates[i].row < coordinates[j].row {
            return true
        } else if coordinates[i].row == coordinates[j].row {
            return coordinates[i].col > coordinates[j].col
        } else {
            return false
        }
    })

    for _, c := range coordinates {
        result = append(result, [2]int{c.row, c.col})
    }

    return result
}

