    func SortArray(array []int) []int {
    if len(array) == 0 {
        return []int{}
    }

    if (array[0]+array[len(array)-1])%2 == 0 {
        for i := 0; i < len(array); i++ {
            for j := i + 1; j < len(array); j++ {
                if array[i] < array[j] {
                    array[i], array[j] = array[j], array[i]
                }
            }
        }
    } else {
        for i := 0; i < len(array); i++ {
            for j := i + 1; j < len(array); j++ {
                if array[i] > array[j] {
                    array[i], array[j] = array[j], array[i]
                }
            }
        }
    }
    return array
}

