func F(n int) []int {
    func F(n int) []int {
    result := make([]int, n)

    cache := make(map[int]int)
    cache[0] = 1
    cache[1] = 1

    for i := 1; i <= n; i++ {
        if i%2 == 0 {
            result[i-1] = cacheFactorial(i, cache)
        } else {
            result[i-1] = cacheSum(i, cache)
        }
    }

    return result
}

func cacheFactorial(num int, cache map[int]int) int {
    if val, ok := cache[num]; ok {
        return val
    } else {
        result := num * cacheFactorial(num-1, cache)
        cache[num] = result
        return result
    }
}

func cacheSum(num int, cache map[int]int) int {
    if val, ok := cache[num]; ok {
        return val
    } else {
        result := num + cacheSum(num-1, cache)
        cache[num] = result
        return result
    }
}

