    func CountNums(arr []int) int {
    count := 0
    for _, num := range arr {
        sum := 0
        n := int(math.Abs(float64(num)))
        for n != 0 {
            sum += n % 10
            n /= 10
        }
        if sum > 0 {
            count++
        }
    }
    return count
}

