    import "sort"

func MoveOneBall(arr []int) bool {
    if len(arr) == 0 {
        return true
    }

    sortedArr := make([]int, len(arr))
    copy(sortedArr, arr)
    sort.Ints(sortedArr)

    for i := 0; i < len(arr); i++ {
        isSorted := true
        for j := 0; j < len(arr); j++ {
            if arr[j] != sortedArr[j] {
                isSorted = false
                break
            }
        }
        if isSorted {
            return true
        }

        lastElement := arr[len(arr)-1]
        copy(arr[1:], arr[:len(arr)-1])
        arr[0] = lastElement
    }

    return false
}

