    import (
    "bytes"
    "unicode"
)

func SelectWords(s string, n int) []string {
    var result []string
    var wordBuffer bytes.Buffer
    consonantCount := 0

    for _, char := range s {
        if unicode.IsLetter(char) {
            if unicode.In(char, unicode.Lower, unicode.Upper) && !isVowel(char) {
                consonantCount++
            }
            wordBuffer.WriteRune(char)
        } else if unicode.IsSpace(char) {
            if consonantCount == n {
                result = append(result, wordBuffer.String())
            }
            wordBuffer.Reset()
            consonantCount = 0
        }
    }

    if consonantCount == n {
        result = append(result, wordBuffer.String())
    }

    return result
}

func isVowel(r rune) bool {
    vowels := "aeiouAEIOU"
    return strings.ContainsRune(vowels, r)
}

