func Maximum(arr []int, k int) []int {
    func Maximum(arr []int, k int) []int {
    if k == 0 {
        return []int{}
    }

    numCount := make(map[int]int)
    for _, num := range arr {
        numCount[num]++
    }

    uniqueNums := make([]int, 0, len(numCount))
    for num := range numCount {
        uniqueNums = append(uniqueNums, num)
    }

    sort.Slice(uniqueNums, func(i, j int) bool {
        return uniqueNums[i] > uniqueNums[j]
    })

    var result []int
    for _, num := range uniqueNums {
        if k == 0 {
            break
        }
        count := numCount[num]
        if count <= k {
            result = append(result, makeSlice(num, count)...)
            k -= count
        } else {
            result = append(result, makeSlice(num, k)...)
            break
        }
    }

    return result
}

func makeSlice(num, count int) []int {
    res := make([]int, count)
    for i := 0; i < count; i++ {
        res[i] = num
    }
    return res
}

