    }

    type IntPair struct {
        originalIndex int
        digitSum      int
    }

    pairs := make([]IntPair, len(nums))
    for i, num := range nums {
        sum := 0
        if num < 0 {
            sum = -1
        }
        for num != 0 {
            sum += num % 10
            num /= 10
        }
        pairs[i] = IntPair{i, sum}
    }

    sort.Slice(pairs, func(i, j int) bool {
        if pairs[i].digitSum == pairs[j].digitSum {
            return pairs[i].originalIndex < pairs[j].originalIndex
        }
        return pairs[i].digitSum < pairs[j].digitSum
    })

    sorted := make([]int, len(nums))
    for i, pair := range pairs {
        sorted[i] = nums[pair.originalIndex]
    }

    return sorted
}

