    import "math"

func Compare(game, guess []int) []int {
    result := make([]int, len(game))

    // Create a hash map to store the correct guesses
    correctGuesses := make(map[int]int)
    for i, score := range game {
        correctGuesses[i] = score
    }

    // Calculate the differences between guesses and scores
    for i, g := range guess {
        if g != correctGuesses[i] {
            result[i] = int(math.Abs(float64(g - correctGuesses[i])))
        }
    }

    return result
}

